package com.autoops.execution.service;import com.autoops.execution.entity.*;import com.autoops.execution.repository.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.time.Instant;@Service public class ExecutionControlService{private final ExecutionRepository executions;private final StepRunRepository steps;public ExecutionControlService(ExecutionRepository e,StepRunRepository s){executions=e;steps=s;}@Transactional public Execution stop(Long id){var e=executions.findById(id).orElseThrow();if("SUCCESS".equals(e.getStatus())||"FAILED".equals(e.getStatus()))return e;e.setStatus("CANCELLED");e.setFinishedAt(Instant.now());return executions.save(e);}@Transactional public StepRun retry(Long stepId){var old=steps.findById(stepId).orElseThrow();var n=new StepRun();n.setMachineRunId(old.getMachineRunId());n.setResolvedCommand(old.getResolvedCommand());n.setStatus("PENDING");n.setAttemptNumber(old.getAttemptNumber()+1);n.setRetryOfStepRunId(old.getId());return steps.save(n);}}
